<?php
/**
 * TEST ONLY (never packaged). Builds a DoajPaEvaluationContext from the Stage 03 fixture journals
 * (tests/stage03/fixtures/sites.json, generated by tests/crawler/fixtures/stage03_sites.py) exactly as the crawler and
 * the orchestrator would: real HTML extractor, ADR-011 main-content language heuristic, the same acquisition states and
 * the same three evidence rows per HTML page. PDF text is given directly (pdftotext output).
 */
$doajPaRoot = dirname(__FILE__) . '/../..';
require_once($doajPaRoot . '/classes/crawler/DoajPaUrlTools.inc.php');
require_once($doajPaRoot . '/classes/crawler/DoajPaPageClassifier.inc.php');
require_once($doajPaRoot . '/classes/extract/DoajPaHtmlExtractor.inc.php');
require_once($doajPaRoot . '/classes/extract/DoajPaLanguageHeuristic.inc.php');
require_once($doajPaRoot . '/classes/framework/DoajPaEvaluationContext.inc.php');
require_once($doajPaRoot . '/classes/framework/DoajPaOutcomeGuard.inc.php');
require_once($doajPaRoot . '/classes/rules/DoajPaCandidateRule.inc.php');
require_once($doajPaRoot . '/classes/rules/DoajPaFormGuideBuilder.inc.php');

class DoajPaRuleFixture {

	const FINISHED = '2026-10-01 12:00:00';
	private static $sites = null;

	public static function sites() {
		if (self::$sites === null) self::$sites = json_decode(file_get_contents(dirname(__FILE__) . '/../stage03/fixtures/sites.json'), true);
		return self::$sites;
	}

	/** @return array path => [kind, body] of one fixture journal */
	public static function pages($site) {
		$s = self::sites();
		$out = array();
		foreach ($s['sites'][$site] as $p) $out[$p['path']] = array($p['kind'], $p['body']);
		return $out;
	}

	/**
	 * @param $pages array path => [kind, body] (see pages())
	 * @param $opts array limitsHit (string[]), site (name used in URLs), depth (path => clicks from the homepage),
	 *  finalUrl (path => URL after redirects), mediaType (path => media type of a kind "other" file)
	 * @return DoajPaEvaluationContext
	 */
	public static function context($pages, $opts = array()) {
		static $extracted = array();
		$s = self::sites();
		$site = isset($opts['site']) ? $opts['site'] : 'x';
		$resources = array(); $evidence = array(); $rid = 0; $eid = 0;
		foreach ($pages as $path => $page) {
			list($kind, $body) = $page;
			$url = $s['origin'] . $s['prefix'] . '/' . $site . $path;
			$type = DoajPaPageClassifier::classify($path);
			$depth = $type === 'home' ? 0 : (in_array($type, array('issue', 'article_list'), true) ? 2 : (in_array($type, array('article'), true) ? 3 : (in_array($type, array('galley', 'file'), true) ? 4 : 1)));
			$rid++;
			$r = array('id' => $rid, 'url' => $url, 'urlSha256' => hash('sha256', $url), 'pageType' => $type, 'httpStatus' => 200, 'acquisition' => 'retrieved',
				'reason' => null, 'contentSha256' => hash('sha256', is_string($body) ? $body : json_encode($body)), 'finalUrl' => $url,
				'mediaType' => $kind === 'pdf' ? 'application/pdf' : 'text/html', 'depth' => $depth, 'mainRegion' => null, 'linkText' => '');
			if (isset($opts['depth'][$path])) $r['depth'] = $opts['depth'][$path];
			if (isset($opts['finalUrl'][$path])) $r['finalUrl'] = $opts['finalUrl'][$path];
			$rows = array();
			$language = null;
			if ($kind === 'status') {
				$r['httpStatus'] = (int) $body; $r['acquisition'] = 'inaccessible'; $r['reason'] = 'access_restricted_http_' . $body; $r['contentSha256'] = null;
			} elseif ($kind === 'other') {
				// A retrieved file that is neither HTML nor PDF (for example a word-processor file): no text is read.
				$r['mediaType'] = isset($opts['mediaType'][$path]) ? $opts['mediaType'][$path] : 'application/octet-stream';
			} elseif ($kind === 'html') {
				$ck = hash('sha256', $url . "\0" . $body);
				if (!isset($extracted[$ck])) {
					if (count($extracted) > 4000) $extracted = array();
					$x0 = DoajPaHtmlExtractor::extract($body, 'utf-8', $url);
					$extracted[$ck] = array($x0, DoajPaLanguageHeuristic::assess($x0['mainText'], $x0['lang']));
				}
				list($x, $language) = $extracted[$ck];
				$r['mainRegion'] = $x['mainRegion'];
				if (trim($x['mainText']) !== '') $rows[] = array('html_main_content', $x['mainText'], 'html_page', $x['title']);
				if ($x['structured']) $rows[] = array('html_structured', implode("\n", $x['structured']), 'html_page', $x['title']);
				if (trim($x['text']) !== '') $rows[] = array('html_text_extraction', $x['text'], 'html_page', $x['title']);
			} else {
				$text = implode("\n", $body);
				$language = DoajPaLanguageHeuristic::assess($text, null);
				$rows[] = array('pdftotext_extraction', $text, 'pdf', null);
			}
			if ($language !== null) {
				$v = $language['verdict'];
				$r['acquisition'] = $v === 'non_english' ? 'unsupported_language' : ($v === 'mixed' ? 'ambiguous' : 'retrieved');
				if ($v !== 'english') $r['reason'] = 'language_' . $v;
			}
			$resources[$rid] = $r;
			foreach ($rows as $row) {
				$eid++;
				$verified = $r['acquisition'] === 'retrieved' && $r['reason'] === null && $language !== null && $language['verdict'] === 'english';
				$evidence[$eid] = array('id' => $eid, 'resourceId' => $rid, 'url' => $url, 'title' => $row[3], 'sourceType' => $row[2], 'pageType' => $type,
					'quote' => $row[1], 'quoteSha256' => hash('sha256', $row[1]), 'acquisition' => $r['acquisition'],
					'language' => $language === null ? 'unknown' : $language['verdict'], 'provenance' => true, 'verifiedEnglish' => $verified,
					'method' => $row[0], 'location' => '');
			}
		}
		$coverage = array('finishedAtUtc' => self::FINISHED, 'limitsHit' => isset($opts['limitsHit']) ? $opts['limitsHit'] : array());
		return new DoajPaEvaluationContext($evidence, $resources, $coverage);
	}

	/** @return array key => guarded outcome for every candidate criterion */
	public static function evaluate($context) {
		$out = array();
		foreach (DoajPaCandidateRule::all() as $rule) {
			$raw = $rule->evaluate($context);
			$out[$rule->key()] = DoajPaOutcomeGuard::apply($raw, $context->guardView(), $rule->key()) + array('raw' => $raw);
		}
		return $out;
	}

	/** @return array FQ answers */
	public static function formGuide($context, $outcomes) {
		$d = DoajPaCandidateDataset::data();
		$b = new DoajPaFormGuideBuilder(DoajPaFacts::of($context), $outcomes, $d['fqMapping']);
		return $b->build();
	}
}
